/* NAMED (Nov 25 2026, HOTFIX-G1): NOTHING TO TAP UNDER THE GUIDE TAB, ONE CONTROL AT A TIME. The Guide's tab
   (scripts/termaximus-guide.js) is 32 px wide at the left edge of a phone, over the page. BEFORE (LR-3B) the whole page
   was pushed 40 px right to clear it, which squeezed HQ and every other page; that is gone. AFTER, only each control (or
   its own row) that the tab would cover is moved, so its left edge is 40 px from the screen's (the tab and an 8 px gap).
   Each selector names one page's own control; no page, card or container moves. browserCheckPhone's PHONE_COMPARE holds
   every other element of every page to its f73aec1 phone baseline, and PHONE_GUIDE finds anything still under the tab. */
/* every agent page (ads, analytics, broker, community, content, email, etsy, executive, influencer, operations,
   publicist, R&D, reputation, sales, SEO, social, store, vertical marketing): Refresh Data and Open Dashboard's row,
   and the Run / History tab row (16 px from the edge) */
.toolbar > div:has(> #refreshBtn), .deck-header-actions:has(> #refreshBtn) { padding-left: 24px; }   /* the second: Executive Agent's header row */
.deck-tabs:has(> #agTab-run) { padding-left: 24px; }
/* HQ (dashboard.html): each link in the list under the orbit (25 px), AI Mailbox and the Command Center's tab row (24 px) */
#orbitTop .hq-list .hq-link { margin-left: 15px; }
#toggleAiMailbox { margin-left: 16px; }
.deck-tabs:has(> #ccTab-command) { padding-left: 16px; }
/* AI Agents (ai-agents.html): each agent's row in the list (17 px) */
.page:not([data-ag-view="grid"]) .ag-list .ag-link { margin-left: 23px; }
/* BizDoc: the Documents / Templates tab row (30 px) and the Start a new document row (24 px) */
.workspace-tabs:has(> .workspace-tab) { padding-left: 10px; }
.newdoc-row:has(> .newdoc-tile-new) { padding-left: 16px; scroll-padding-left: 16px; }   /* a snapping strip: the snap keeps the inset */
/* Business Chat: the message box's row (24 px) */
div:has(> #chatInput) { padding-left: 16px; }
/* Certifications and Proposals: the filter rows (24 px) */
.filter-bar:has(> .filter-btn), .filter-bar:has(> .filter-pill) { padding-left: 16px; }
/* CRM and Inventory: + Add Customer, + Add Item (24 px) */
#addCustomerBtn { margin-left: 16px; }
/* + Add Item shares its row with the item count (space-between) and wraps under it only on a narrow phone: the count gives
   back the same 16 px (a -16 px right margin), so on one line nothing moves and alone on its line the button sits at 40 px */
#addItemBtn { margin-left: 16px; }
.iv-toolbar > #itemCount { margin-right: -16px; }
/* Marketplace: the category tab row and the category chips' row (24 px) */
#tabBar { padding-left: 16px; }
#catFilter { padding-left: 16px; }
/* Prospecting: the Prospects / ... tab row (24 px) */
.ps-tabs:has(> #tabProspects) { padding-left: 16px; }
/* Support: the Share / Copy link row (16 px) */
.sup-row:has(> #supShareBtn) { padding-left: 24px; }
/* a storefront (seller.html): Message and Follow's row, from the Message button (24 px) */
.sf-header > #sfMessage { margin-left: 16px; }
/* its "..." menu wraps under them when the follower count is long: the count gives back the same 16 px (a -16 px right
   margin), so on one line nothing moves, and alone on its line the menu sits at 40 px */
.sf-header > .bf-safety-dots { margin-left: 16px; }
.sf-header > #sfFollowers { margin-right: -16px; }
/* Digital Cards' editor (24 px): the theme row, each colour row, the design tab row, each select, each button row,
   Save / Export / Share's row and the print options' row (the checkbox, 28 px) */
.theme-selector:has(> .theme-btn) { padding-left: 16px; }
.ed-panel .cust-color-row, .cust-color-row:has(> #cardBgColorInp) { padding-left: 16px; }
#cardEdTablist { padding-left: 16px; }
.ed-panel .cust-select { margin-left: 16px; width: calc(100% - 16px); }
.ed-panel .cust-btn-row { padding-left: 16px; }   /* not the Horizontal / Vertical row above the card, already clear at 53 px */
.action-row:has(> #saveBtn) { padding-left: 16px; }
.print-opts-row:has(#bleedCheck) { padding-left: 12px; }
/* Lead Radar: each lead's (and each notice's) row of buttons, I can help, Draft a reply and the rest (25 px) */
.lr-acts { padding-left: 15px; }
/* and Inbound: each item's link, its own row in the list (25 px) */
.lr-open { margin-left: 15px; }
/* the footer's links, on the two pages short enough to bring them under the tab at 360 (Lead Radar, Your data) */
body:has(#lrTabFp) .bf-legal-footer nav, body:has(#neverExported) .bf-legal-footer nav { padding-left: 16px; }
